import get from 'lodash/get'
import { formatMoney, getHardcopyType, getNameOrKeyForDropdown, getTransportValue } from '../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../lang'

export const MARINE_CARGO_BASIC_DETAILS_FORM = 'MARINE_CARGO_BASIC_DETAILS_FORM'

export const getPolicyDetailCard = (data) => {
  const transportType = get(data, 'policy_detail.transportation_type', '')

  let transportDetail = []

  switch (transportType) {
    case 'land':
      transportDetail = [
        {
          head: LANG_STRINGS.vehicleType,
          value: getNameOrKeyForDropdown(data, 'policy_detail.vehicle_type')
        },
        {
          head: LANG_STRINGS.policeNumber,
          value: `${get(data, 'policy_detail.region_code', '-')} ${get(data, 'policy_detail.vehicle_plate_no', '-')}`
        }
      ]
      break
    case 'sea':
      transportDetail = [
        {
          head: LANG_STRINGS.shipType,
          value: getNameOrKeyForDropdown(data, 'policy_detail.ship_type')
        },
        {
          head: LANG_STRINGS.shipMaterials,
          value: getNameOrKeyForDropdown(data, 'policy_detail.ship_material')
        },
        {
          head: LANG_STRINGS.shipClassification,
          value: getNameOrKeyForDropdown(data, 'policy_detail.ship_class')
        },
        {
          head: LANG_STRINGS.shipManufacturingYear,
          value: get(data, 'policy_detail.year', '-')
        }
      ]
      break
    case 'air':
      transportDetail = [
        {
          head: LANG_STRINGS.airPlaneRegistrationNo,
          value: get(data, 'policy_detail.plane_registration_no', '-')
        },
        {
          head: LANG_STRINGS.airplaneRegistrationName,
          value: get(data, 'policy_detail.airplane_name', '-')
        },
        {
          head: LANG_STRINGS.flightNo,
          value: get(data, 'policy_detail.flight_no', '-')
        }
      ]
      break
    default:
  }
  const fields = [
    {
      head: LANG_STRINGS.modeOfTransport,
      value: getTransportValue(get(data, 'policy_detail.transportation_type', '-'))
    },
    ...transportDetail,
    {
      head: LANG_STRINGS.totalSumInsured,
      value: formatMoney(get(data, 'policy_detail.sum_insured', ''))
    }
  ]
  return fields
}

export const getItemDetailCard = (data) => {
  const fields = [
    {
      head: LANG_STRINGS.typeOfGood,
      value: getNameOrKeyForDropdown(data, 'policy_detail.type_of_goods')
    },
    {
      head: LANG_STRINGS.insuredItemDetail,
      value: get(data, 'policy_detail.details', '-'),
      newline: true
    }]

  const transportType = get(data, 'policy_detail.transportation_type', '')
  if (transportType === 'sea') {
    fields.push({
      head: LANG_STRINGS.registrationNumberIMO,
      value: get(data, 'policy_detail.registration_number', '-')
    })
  }
  return fields
}

