export const getAttachmentDetailCard = (data) => {
  const fields = [
    {
      head: LANG_STRINGS.billAWB,
      value: get(data, 'policy_detail.bill_url', ''),
      newline: true,
      type: 'img'
    }]
  if (get(data, 'policy_detail.invoice_url', '')) {
    fields.push({
      head: LANG_STRINGS.invoice,
      value: get(data, 'policy_detail.invoice_url', ''),
      newline: true,
      type: 'img'
    })
  }
  return fields
}

