import { MARINE_CARGO_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case MARINE_CARGO_ACTIONS.GET_REGION_CODES:
    case MARINE_CARGO_ACTIONS.GET_SHIP_MATERIAL:
    case MARINE_CARGO_ACTIONS.GET_PACKAGES:
    case MARINE_CARGO_ACTIONS.GET_PACKAGE_DETAIL:
    case MARINE_CARGO_ACTIONS.CREATE_APPLICATION:
    case MARINE_CARGO_ACTIONS.UPDATE_APPLICATION:
    case MARINE_CARGO_ACTIONS.UPDATE_CUSTOMER_APPLICATION:
    case MARINE_CARGO_ACTIONS.SUBMIT_APPLICATION:
    case MARINE_CARGO_ACTIONS.CHANGE_DISCOUNT:
    case MARINE_CARGO_ACTIONS.GET_APPLICATION_DETAIL:
    case MARINE_CARGO_ACTIONS.GET_CUSTOMER_APPLICATION_DETAIL:
    case MARINE_CARGO_ACTIONS.GET_COUNTRY_LIST:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducer
