import { Button, Container } from '../../../../../../components'
import { formatMoney, getParamsFromUri } from '../../../../../../helpers/utility'
import { PackageDetailStyle } from './index.style'
import { withRouter } from 'react-router'
import StepsHeader from '../../../../../../components/StepsHeader'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import { useCreateApplication, useGetPackageDetail } from '../../../state/hooks/useMarineCargo'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useCallback, useEffect, useState } from 'react'
import { getFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { MARINE_CARGO_BASIC_DETAILS_FORM } from '../../../constants'
import { MARINE_CARGO_PROTECTION } from '../../../../../../constants/pkgCode'
import { get } from 'lodash'
import SendQuotationModal from '../../../../../../components/SendQuotationModal'
import { Row } from '../../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../lang'
import QuickViewPackageCard from '../../../../../../components/QuickViewPackageCard'
import InsuranceInfoCard from '../../../../../../components/InsuranceInfoCard'
import TransactionCard from '../../../../../../components/TransactionCard'
import isEmpty from 'lodash/isEmpty'

function MarineCargoPackageDetail (props) {
  const packageCode = getParamsFromUri.call({ props }, 'pkgCode')
  const [selectedBranch, setSelectedBranch] = useState({})
  const [{ GET_PACKAGE_DETAIL_LOADER, CREATE_APPLICATION_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getPackageDetailData = {} }, getPackageDetailRequest] = useGetPackageDetail()
  const [{ createApplicationData }, createApplicationRequest] = useCreateApplication()

  const [discount, setDiscount] = useState(get('getPackageDetailData', 'discount', 0))
  const [showQuotationModal, setShowQuotationModal] = useState(false)
  const formDetails = getFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM)

  const [
    {
      GET_PACKAGE_DETAIL_ERROR, getPackageDetailStatus,
      CREATE_APPLICATION_ERROR, createApplicationStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (GET_PACKAGE_DETAIL_LOADER === undefined) {
      const formDetails = getFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM)
      getPackageDetailRequest({
        body: { ...formDetails, package_type: MARINE_CARGO_PROTECTION },
        package_code: packageCode
      })
    }
  }, [getPackageDetailRequest,
    GET_PACKAGE_DETAIL_LOADER, packageCode
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PACKAGE_DETAIL_LOADER: undefined,
        CREATE_APPLICATION_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_PACKAGE_DETAIL_ERROR && getPackageDetailStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getPackageDetailStatus
      })
      dispatchError(resetError({
        getPackageDetailStatus: ''
      }))
    }
    if (CREATE_APPLICATION_ERROR && createApplicationStatus) {
      ShowSnackbar.error({
        visible: true,
        text: createApplicationStatus
      })
      dispatchError(resetError({
        createApplicationStatus: ''
      }))
    }

    if (createApplicationStatus === 'success') {
      props.history.push(`/marine_cargo/packages/${createApplicationData.id}/form`)
      dispatchError(resetError({
        createApplicationStatus: ''
      }))
    }
  }, [GET_PACKAGE_DETAIL_ERROR, getPackageDetailStatus,
    CREATE_APPLICATION_ERROR, createApplicationStatus,
    dispatchError, props.history, createApplicationData
  ])

  const handleEditDiscount = useCallback((newDiscount) => {
    setDiscount(newDiscount)
  }, [])

  const handleCloseQuotationModal = useCallback(() => {
    setShowQuotationModal(false)
  }, [])

  const handleSendOffer = useCallback(() => {
    setShowQuotationModal(true)
  }, [])

  const handleBuyPkg = useCallback(() => {
    let branch = selectedBranch
    if (isEmpty(branch)) {
      branch = getPackageDetailData?.provider?.headquarter_branch
    }
    createApplicationRequest({
      body: {
        ...formDetails,
        ...getPackageDetailData,
        code: packageCode,
        discount: discount,
        provider_branch: branch
      }
    })
  }, [createApplicationRequest, discount, formDetails,
    packageCode, getPackageDetailData, selectedBranch
  ])

  const handleBranchSelect = useCallback((branch) => {
    setSelectedBranch(branch)
  }, [])

  const showShipClass = get(getFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM), 'ship_class', '') !== 'non-class'

  let branch = selectedBranch
  if (isEmpty(branch)) {
    branch = getPackageDetailData?.provider?.headquarter_branch
  }

  return (
    <Container
      title='Kargo'
      hideBottomTabs
      displayBackButton
      backBtnId='kargoStepBack_2_pkgDetail'
      loader={GET_PACKAGE_DETAIL_LOADER || CREATE_APPLICATION_LOADER}
    >
      <PackageDetailStyle>
        <StepsHeader leftText='Paket Asuransi' current='2' totalSteps='4' />
        <div className='content'>
          <QuickViewPackageCard
            packageLogo={get(getPackageDetailData, 'provider.logo_url', '')}
            providerName={showShipClass && get(getPackageDetailData, 'provider.name', '')}
            packageName={get(getPackageDetailData, 'name', '')}
            amount={formatMoney(get(getPackageDetailData, 'basic_premium', 0), 0)}
            period={get(getPackageDetailData, 'applicable_period', 0)}
            points={get(getPackageDetailData, 'points', 0)}
          />
          <InsuranceInfoCard
            isShowDisclaimer
            tnc={get(getPackageDetailData, 'tnc.data', [])}
            benefit={get(getPackageDetailData, 'benefit.data[0].description', '')}
            claims={get(getPackageDetailData, 'claims.[0].description', '')}
            showBranchOption
            selectedBranch={branch}
            onBranchSelect={handleBranchSelect}
            providerCode={getPackageDetailData?.provider?.code}
          />
          <TransactionCard
            commission={get(getPackageDetailData, 'commission')}
            maxDiscount={get(getPackageDetailData, 'max_discount')}
            subTotal={get(getPackageDetailData, 'sub_total')}
            discountPercent={get(getPackageDetailData, 'discount_percentage')}
            basicPremium={get(getPackageDetailData, 'basic_premium')}
            totalTax={0}
            stampDuty={get(getPackageDetailData, 'stamp_duty')}
            adminFee={get(getPackageDetailData, 'admin_fee')}
            serviceFee={get(getPackageDetailData, 'service_fee')}
            discount={discount}
            totalBill={get(getPackageDetailData, 'total_bill')}
            handleEditDiscount={handleEditDiscount}
          />
        </div>
        <Row className='cargo-pkg-detail-btn-box' justify='space-between'>
          <Button
            onClick={handleSendOffer}
            backgroundColor={AgentColorPallette.cyanBlue}
            color={AgentColorPallette.white}
            id='cargo-detail-offer-click'
            className='pkg-detail-btn'
          >
            {LANG_STRINGS.sendOffer}
          </Button>
          <div className='space' />
          <Button
            onClick={handleBuyPkg}
            id='cargo-detail-agent-buy-pkg-click'
            className='pkg-detail-btn'
          >
            {LANG_STRINGS.buyThisPackage}
          </Button>
        </Row>
        {
          showQuotationModal && (
            <SendQuotationModal
              providerBranch={branch}
              showQuotationModal={showQuotationModal}
              quotation={{
                ...formDetails,
                code: packageCode,
                premium: {
                  period: get(getPackageDetailData, 'applicable_period', 0)
                },
                discount: discount
              }}
              pkgDetail={getPackageDetailData}
              id='mobilDetailPkgOfferStep-2'
              onClose={handleCloseQuotationModal}
            />
          )
        }
        <ShowSnackbar hideOkay />
      </PackageDetailStyle>
    </Container>
  )
}

export default withRouter(MarineCargoPackageDetail)
